descriptor.templateCss:
.hyv-energy-balance-card {
  box-sizing: border-box;
  width: 100%;
  height: 100%;
  background: linear-gradient(160deg, rgba(14, 25, 16, 0.98) 0%, rgba(8, 15, 9, 0.99) 100%);
  border-radius: 10px;
  border: 1px solid rgba(100, 184, 86, 0.22);
  border-top: 3px solid #F59E0B;
  padding: 14px 18px;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  font-family: 'Roboto', -apple-system, sans-serif;
  color: #f8fafc;
}
.hyv-eb-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  border-bottom: 1px solid rgba(255, 255, 255, 0.08);
  padding-bottom: 10px;
}
.hyv-eb-title-box {
  display: flex;
  align-items: center;
  gap: 10px;
}
.hyv-eb-icon {
  font-size: 20px;
  color: #F59E0B;
}
.hyv-eb-title {
  font-size: 14px;
  font-weight: 700;
  letter-spacing: 0.5px;
  color: #f8fafc;
}
.hyv-eb-sub {
  font-size: 11px;
  color: #94a3b8;
}
.hyv-eb-badge {
  font-size: 10px;
  font-weight: 600;
  padding: 3px 8px;
  border-radius: 4px;
  background: rgba(100, 184, 86, 0.15);
  color: #64B856;
  border: 1px solid rgba(100, 184, 86, 0.3);
}
.hyv-eb-chips {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 8px;
  margin: 10px 0;
}
.hyv-eb-chip {
  background: rgba(255, 255, 255, 0.03);
  border-radius: 6px;
  padding: 8px 10px;
  display: flex;
  flex-direction: column;
  gap: 4px;
  border-left: 3px solid #64748b;
}
.hyv-eb-chip.solar { border-left-color: #F59E0B; }
.hyv-eb-chip.bess-chg { border-left-color: #A855F7; }
.hyv-eb-chip.bess-dis { border-left-color: #06B6D4; }
.hyv-eb-chip.load { border-left-color: #10B981; }
.chip-label {
  font-size: 10px;
  color: #94a3b8;
  font-weight: 500;
}
.chip-val {
  font-size: 14px;
  font-weight: 700;
  color: #f8fafc;
}
.chip-val small {
  font-size: 10px;
  font-weight: 400;
  color: #94a3b8;
}
.hyv-eb-charts-row {
  display: grid;
  grid-template-columns: 1.2fr 0.8fr;
  gap: 14px;
  align-items: center;
  flex: 1;
}
.chart-caption {
  font-size: 10px;
  font-weight: 600;
  color: #94a3b8;
  text-transform: uppercase;
  letter-spacing: 0.5px;
  margin-bottom: 6px;
}
.bars-container {
  display: flex;
  justify-content: space-around;
  align-items: flex-end;
  height: 100px;
  padding: 0 10px;
  background: rgba(0, 0, 0, 0.2);
  border-radius: 6px;
  border-bottom: 2px solid rgba(255, 255, 255, 0.1);
}
.bar-group {
  display: flex;
  flex-direction: column;
  align-items: center;
  height: 100%;
  justify-content: flex-end;
  width: 22%;
}
.bar-fill {
  width: 100%;
  border-radius: 4px 4px 0 0;
  transition: height 0.6s cubic-bezier(0.4, 0, 0.2, 1);
  min-height: 4px;
}
.bar-fill.solar { background: linear-gradient(180deg, #FBBF24 0%, #D97706 100%); }
.bar-fill.bess-chg { background: linear-gradient(180deg, #C084FC 0%, #7E22CE 100%); }
.bar-fill.bess-dis { background: linear-gradient(180deg, #22D3EE 0%, #0891B2 100%); }
.bar-fill.load { background: linear-gradient(180deg, #34D399 0%, #059669 100%); }
.bar-label {
  font-size: 9px;
  color: #94a3b8;
  margin-top: 4px;
}
.donut-wrap {
  position: relative;
  width: 90px;
  height: 90px;
  margin: 0 auto;
}
.donut-svg {
  width: 100%;
  height: 100%;
  transform: rotate(-90deg);
}
.donut-bg {
  fill: none;
  stroke: rgba(255, 255, 255, 0.08);
  stroke-width: 12;
}
.donut-seg-solar {
  fill: none;
  stroke: #F59E0B;
  stroke-width: 12;
  stroke-linecap: round;
  transition: stroke-dasharray 0.6s ease;
}
.donut-seg-bess {
  fill: none;
  stroke: #A855F7;
  stroke-width: 12;
  transition: stroke-dasharray 0.6s ease;
}
.donut-center-text {
  position: absolute;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
  text-align: center;
}
.donut-pct {
  font-size: 13px;
  font-weight: 700;
  color: #f8fafc;
}
.donut-lbl {
  font-size: 8px;
  color: #94a3b8;
}
.donut-legend {
  display: flex;
  justify-content: center;
  gap: 12px;
  margin-top: 6px;
  font-size: 9px;
  color: #94a3b8;
}
.donut-legend span {
  display: flex;
  align-items: center;
  gap: 4px;
}
.donut-legend .dot {
  width: 6px;
  height: 6px;
  border-radius: 50%;
}
.donut-legend .dot.solar { background: #F59E0B; }
.donut-legend .dot.bess { background: #A855F7; }

descriptor.controllerScript:
self.onInit = function() {
  self.onDataUpdated();
};

self.onDataUpdated = function() {
  var data = self.ctx.data || [];
  var solarKwh = 0.0;
  var loadKwh = 0.0;
  var bessChgKwh = 0.0;
  var bessDisKwh = 0.0;

  for (var i = 0; i < data.length; i++) {
    var item = data[i];
    if (item.data && item.data.length > 0) {
      var name = (item.dataKey && item.dataKey.name) ? item.dataKey.name : '';
      var val = parseFloat(item.data[item.data.length - 1][1]) || 0.0;
      if (name.indexOf('solar') !== -1 || name.indexOf('epv') !== -1) {
        if (val > solarKwh) solarKwh = val;
      } else if (name.indexOf('load') !== -1 || name.indexOf('carga_hoy') !== -1) {
        if (val > loadKwh) loadKwh = val;
      } else if (name.indexOf('carga') !== -1 || name.indexOf('almacenada') !== -1) {
        if (val > bessChgKwh) bessChgKwh = val;
      } else if (name.indexOf('descarga') !== -1) {
        if (val > bessDisKwh) bessDisKwh = val;
      }
    }
  }

  // Update KPI text
  var elSolar = document.getElementById('eb-val-solar');
  var elLoad = document.getElementById('eb-val-load');
  var elBessChg = document.getElementById('eb-val-bess-chg');
  var elBessDis = document.getElementById('eb-val-bess-dis');
  if (elSolar) elSolar.innerHTML = solarKwh.toLocaleString('es-CO', {minimumFractionDigits: 1, maximumFractionDigits: 1}) + ' <small>kWh</small>';
  if (elLoad) elLoad.innerHTML = loadKwh.toLocaleString('es-CO', {minimumFractionDigits: 1, maximumFractionDigits: 1}) + ' <small>kWh</small>';
  if (elBessChg) elBessChg.innerHTML = bessChgKwh.toLocaleString('es-CO', {minimumFractionDigits: 1, maximumFractionDigits: 1}) + ' <small>kWh</small>';
  if (elBessDis) elBessDis.innerHTML = bessDisKwh.toLocaleString('es-CO', {minimumFractionDigits: 1, maximumFractionDigits: 1}) + ' <small>kWh</small>';

  // Update comparison bars
  var maxVal = Math.max(solarKwh, loadKwh, bessChgKwh, bessDisKwh, 1.0);
  var barSolar = document.getElementById('bar-solar');
  var barLoad = document.getElementById('bar-load');
  var barBessChg = document.getElementById('bar-bess-chg');
  var barBessDis = document.getElementById('bar-bess-dis');
  if (barSolar) barSolar.style.height = Math.round((solarKwh / maxVal) * 85) + '%';
  if (barLoad) barLoad.style.height = Math.round((loadKwh / maxVal) * 85) + '%';
  if (barBessChg) barBessChg.style.height = Math.round((bessChgKwh / maxVal) * 85) + '%';
  if (barBessDis) barBessDis.style.height = Math.round((bessDisKwh / maxVal) * 85) + '%';

  // Update Donut
  var totalFlow = solarKwh + bessDisKwh;
  var cCircum = 2 * Math.PI * 40; // ~251.3
  var segSolar = document.getElementById('donut-seg-solar');
  var segBess = document.getElementById('donut-seg-bess');
  if (segSolar && totalFlow > 0) {
    var solarPortion = (solarKwh / totalFlow) * cCircum;
    segSolar.setAttribute('stroke-dasharray', solarPortion.toFixed(1) + ' ' + cCircum.toFixed(1));
    segSolar.setAttribute('stroke-dashoffset', '0');
  }
  if (segBess && totalFlow > 0) {
    var bessPortion = (bessDisKwh / totalFlow) * cCircum;
    segBess.setAttribute('stroke-dasharray', bessPortion.toFixed(1) + ' ' + cCircum.toFixed(1));
    segBess.setAttribute('stroke-dashoffset', '-' + ((solarKwh / totalFlow) * cCircum).toFixed(1));
  }
};
